import React, { useEffect, useState } from 'react';
import { useClassFramework } from '../contexts/ClassFrameworkContext';
import { ClassNote } from '../types/ClassFramework';

interface FloatingTooltipProps {
  className?: string;
}

export function FloatingTooltip({ className = '' }: FloatingTooltipProps) {
  const [position, setPosition] = useState({ top: 100, left: 100 });

  // Copy simulation controls positioning logic
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setPosition({ top: e.clientY - 50, left: e.clientX + 20 });
    };

    document.addEventListener('mousemove', handleMouseMove);
    return () => document.removeEventListener('mousemove', handleMouseMove);
  }, []);

  return (
    <div 
      className="simulation-controls dark-mode"
      style={{
        position: 'fixed',
        top: position.top,
        left: position.left,
        background: 'rgba(45, 45, 45, 0.95)',
        border: '3px solid #007bff',
        borderRadius: '12px',
        padding: '1.5rem',
        zIndex: 99999,
        boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
        backdropFilter: 'blur(10px)',
        minWidth: '300px',
        maxWidth: '400px',
        cursor: 'default',
        userSelect: 'auto',
        transition: 'box-shadow 0.2s',
        pointerEvents: 'auto',
        isolation: 'isolate'
      }}
    >
      <div 
        style={{ 
          textAlign: 'center', 
          marginBottom: '1rem',
          borderBottom: '2px solid #007bff',
          paddingBottom: '0.5rem',
          cursor: 'default',
          userSelect: 'none',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          pointerEvents: 'auto',
          position: 'relative',
          zIndex: 99999
        }}
      >
        <div style={{ flex: 1 }}>
          <h3 style={{ 
            margin: 0, 
            color: '#007bff', 
            fontSize: '1.2rem',
            fontWeight: 'bold',
            pointerEvents: 'none'
          }}>
            🎓 Class Framework Tooltip
          </h3>
          <div style={{ 
            fontSize: '0.9rem', 
            color: '#b0b0b0',
            marginTop: '0.25rem',
            pointerEvents: 'none'
          }}>
            Hover over browser bar elements to see information
          </div>
        </div>
      </div>

      <div style={{ 
        fontSize: '1rem', 
        color: '#ffffff',
        textAlign: 'center',
        padding: '1rem'
      }}>
        <p>This tooltip follows your mouse cursor.</p>
        <p style={{ marginTop: '0.5rem', fontSize: '0.9rem', color: '#b0b0b0' }}>
          Try hovering over the Norton browser bar elements to see educational information about scareware tactics.
        </p>
      </div>
    </div>
  );
}
